/** Native read-only ONVIF inspector: device information, profiles and RTSP stream URI. */
public final class OnvifClientActivity extends Activity {
    private ServiceEndpoint endpoint;
    private EditText user,password,serviceUrl;
    private TextView status;
    private LinearLayout results;
    private ProgressBar progress;
    private String mediaUrl="";
    private final List<Profile> profiles=new ArrayList<Profile>();
    @Override protected void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);endpoint=ServiceEndpoint.from(getIntent());build();}
    private void build(){LinearLayout root=ClientUi.root(this);root.addView(ClientUi.header(this,"ONVIF Camera Center","Read-only сведения, профили и RTSP URI"));LinearLayout page=ClientUi.page(this);ScrollView sc=new ScrollView(this);sc.addView(page);root.addView(sc,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,0,1f));LinearLayout c=ClientUi.card(this,15);serviceUrl=ClientUi.input(this,"Device service URL");serviceUrl.setText(defaultUrl());user=ClientUi.input(this,"Пользователь");password=ClientUi.input(this,"Пароль");password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);c.addView(serviceUrl,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ClientUi.dp(this,46)));c.addView(user,ClientUi.margins(this,ViewGroup.LayoutParams.MATCH_PARENT,ClientUi.dp(this,46),0,8,0,0));c.addView(password,ClientUi.margins(this,ViewGroup.LayoutParams.MATCH_PARENT,ClientUi.dp(this,46),0,8,0,0));TextView inspect=ClientUi.button(this,"Получить сведения и профили",true);c.addView(inspect,ClientUi.margins(this,ViewGroup.LayoutParams.MATCH_PARENT,ClientUi.dp(this,48),0,10,0,0));progress=new ProgressBar(this);progress.setVisibility(View.GONE);c.addView(progress,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ClientUi.dp(this,34)));status=ClientUi.text(this,"Учётные данные не сохраняются. Конфигурация камеры не изменяется.",12,ClientUi.MUTED,false);c.addView(status);page.addView(c);results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);page.addView(results,ClientUi.margins(this,ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT,0,12,0,0));inspect.setOnClickListener(new View.OnClickListener(){@Override public void onClick(View v){inspect();}});setContentView(root);}
    private String defaultUrl(){if(endpoint.location.startsWith("http://")||endpoint.location.startsWith("https://"))return endpoint.location;return"http://"+endpoint.host+":"+(endpoint.port>0&&endpoint.port!=3702?endpoint.port:80)+"/onvif/device_service";}
    private void inspect(){progress.setVisibility(View.VISIBLE);status.setText("Запрос ONVIF…");results.removeAllViews();profiles.clear();new Thread(new Runnable(){@Override public void run(){try{String base=serviceUrl.getText().toString().trim();final String deviceInfo=soap(base,"http://www.onvif.org/ver10/device/wsdl/GetDeviceInformation",body("tds:GetDeviceInformation","xmlns:tds=\"http://www.onvif.org/ver10/device/wsdl\""));final String capabilities=soap(base,"http://www.onvif.org/ver10/device/wsdl/GetCapabilities",bodyRaw("<tds:GetCapabilities xmlns:tds=\"http://www.onvif.org/ver10/device/wsdl\"><tds:Category>All</tds:Category></tds:GetCapabilities>"));mediaUrl=findMediaXAddr(capabilities);if(mediaUrl.length()==0)mediaUrl=findAnyXAddr(capabilities);final String profilesXml=mediaUrl.length()>0?soap(mediaUrl,"http://www.onvif.org/ver10/media/wsdl/GetProfiles",body("trt:GetProfiles","xmlns:trt=\"http://www.onvif.org/ver10/media/wsdl\"")):"";profiles.addAll(parseProfiles(profilesXml));runOnUiThread(new Runnable(){@Override public void run(){progress.setVisibility(View.GONE);status.setText("ONVIF обнаружен · профилей: "+profiles.size());renderDevice(deviceInfo,capabilities);renderProfiles();}});}catch(final Exception e){runOnUiThread(new Runnable(){@Override public void run(){progress.setVisibility(View.GONE);status.setText("Ошибка ONVIF: "+e.getMessage());}});}}}).start();}
    private void renderDevice(String info,String caps){LinearLayout c=ClientUi.card(this,14);c.addView(ClientUi.text(this,"Устройство",17,ClientUi.NAVY,true));add(c,"Производитель",findText(info,"Manufacturer",null));add(c,"Модель",findText(info,"Model",null));add(c,"Firmware",findText(info,"FirmwareVersion",null));add(c,"Серийный номер",findText(info,"SerialNumber",null));add(c,"Hardware ID",findText(info,"HardwareId",null));add(c,"Media XAddr",mediaUrl);results.addView(c);}
    private void renderProfiles(){if(profiles.isEmpty())return;LinearLayout c=ClientUi.card(this,14);c.addView(ClientUi.text(this,"Профили видео",17,ClientUi.NAVY,true));for(final Profile p:profiles){TextView b=ClientUi.button(this,(p.name.length()>0?p.name:"Профиль")+" · "+p.token,false);b.setOnClickListener(new View.OnClickListener(){@Override public void onClick(View v){resolveStream(p);}});c.addView(b,ClientUi.margins(this,ViewGroup.LayoutParams.MATCH_PARENT,ClientUi.dp(this,46),0,6,0,0));}results.addView(c,ClientUi.margins(this,ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT,0,10,0,0));}
    private void resolveStream(final Profile p){status.setText("Получение RTSP URI…");new Thread(new Runnable(){@Override public void run(){try{String xml="<trt:GetStreamUri xmlns:trt=\"http://www.onvif.org/ver10/media/wsdl\"><trt:StreamSetup><tt:Stream xmlns:tt=\"http://www.onvif.org/ver10/schema\">RTP-Unicast</tt:Stream><tt:Transport xmlns:tt=\"http://www.onvif.org/ver10/schema\"><tt:Protocol>RTSP</tt:Protocol></tt:Transport></trt:StreamSetup><trt:ProfileToken>"+escape(p.token)+"</trt:ProfileToken></trt:GetStreamUri>";String response=soap(mediaUrl,"http://www.onvif.org/ver10/media/wsdl/GetStreamUri",bodyRaw(xml));final String uri=findText(response,"Uri",null);runOnUiThread(new Runnable(){@Override public void run(){if(uri.length()==0){status.setText("RTSP URI не получен");return;}status.setText(uri);ServiceEndpoint rtsp=new ServiceEndpoint();rtsp.host=endpoint.host;rtsp.port=554;rtsp.protocol="RTSP";rtsp.displayName=p.name;rtsp.uri=uri;ProtocolRouter.openBuiltIn(OnvifClientActivity.this,rtsp);}});}catch(final Exception e){runOnUiThread(new Runnable(){@Override public void run(){status.setText("Ошибка: "+e.getMessage());}});}}}).start();}
    private String soap(String url,String action,String body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/soap+xml; charset=utf-8; action=\""+action+"\"");byte[] payload=envelope(body).getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(payload.length);OutputStream out=c.getOutputStream();out.write(payload);out.close();int code=c.getResponseCode();InputStream in=code>=200&&code<400?c.getInputStream():c.getErrorStream();byte[] data=readAll(in);c.disconnect();if(code<200||code>=400)throw new Exception("HTTP "+code+" · "+new String(data,StandardCharsets.UTF_8));return new String(data,StandardCharsets.UTF_8);}
    private String envelope(String inner)throws Exception{return"<?xml version=\"1.0\" encoding=\"UTF-8\"?><s:Envelope xmlns:s=\"http://www.w3.org/2003/05/soap-envelope\"><s:Header>"+security()+"</s:Header><s:Body>"+inner+"</s:Body></s:Envelope>";}
    private String security()throws Exception{if(user.getText().toString().length()==0)return"";byte[] nonce=new byte[16];new java.security.SecureRandom().nextBytes(nonce);SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",Locale.US);f.setTimeZone(TimeZone.getTimeZone("UTC"));String created=f.format(new Date());MessageDigest sha=MessageDigest.getInstance("SHA-1");sha.update(nonce);sha.update(created.getBytes(StandardCharsets.UTF_8));sha.update(password.getText().toString().getBytes(StandardCharsets.UTF_8));String digest=Base64.encodeToString(sha.digest(),Base64.NO_WRAP);return"<wsse:Security s:mustUnderstand=\"1\" xmlns:wsse=\"http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd\" xmlns:wsu=\"http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd\"><wsse:UsernameToken><wsse:Username>"+escape(user.getText().toString())+"</wsse:Username><wsse:Password Type=\"http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-username-token-profile-1.0#PasswordDigest\">"+digest+"</wsse:Password><wsse:Nonce EncodingType=\"http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-soap-message-security-1.0#Base64Binary\">"+Base64.encodeToString(nonce,Base64.NO_WRAP)+"</wsse:Nonce><wsu:Created>"+created+"</wsu:Created></wsse:UsernameToken></wsse:Security>";}
    private static String body(String tag,String ns){return"<"+tag+" "+ns+"/>";}private static String bodyRaw(String x){return x;}
    private static List<Profile> parseProfiles(String xml)throws Exception{List<Profile> out=new ArrayList<Profile>();if(xml.length()==0)return out;XmlPullParser p=XmlPullParserFactory.newInstance().newPullParser();p.setInput(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)),"UTF-8");Profile cur=null;String tag="";int ev=p.getEventType();while(ev!=XmlPullParser.END_DOCUMENT){if(ev==XmlPullParser.START_TAG){tag=local(p.getName());if("Profiles".equals(tag)||"profiles".equals(tag)){cur=new Profile();for(int i=0;i<p.getAttributeCount();i++)if("token".equals(local(p.getAttributeName(i))))cur.token=p.getAttributeValue(i);}}else if(ev==XmlPullParser.TEXT&&cur!=null&&"Name".equals(tag))cur.name=p.getText().trim();else if(ev==XmlPullParser.END_TAG&&cur!=null&&("Profiles".equals(local(p.getName()))||"profiles".equals(local(p.getName())))){out.add(cur);cur=null;}ev=p.next();}return out;}
    private static String findText(String xml,String wanted,String context){try{XmlPullParser p=XmlPullParserFactory.newInstance().newPullParser();p.setInput(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)),"UTF-8");String tag="",parent="";int depth=0;int ev=p.getEventType();while(ev!=XmlPullParser.END_DOCUMENT){if(ev==XmlPullParser.START_TAG){parent=tag;tag=local(p.getName());depth++;}else if(ev==XmlPullParser.TEXT&&wanted.equals(tag)){String v=p.getText().trim();if(v.length()>0&&(context==null||xml.contains(context)))return v;}else if(ev==XmlPullParser.END_TAG){depth--;}ev=p.next();}}catch(Exception ignored){}return"";}
    private static String findMediaXAddr(String xml){try{XmlPullParser p=XmlPullParserFactory.newInstance().newPullParser();p.setInput(new ByteArrayInputStream(xml.getBytes(StandardCharsets.UTF_8)),"UTF-8");int mediaDepth=-1;int depth=0;String tag="";int ev=p.getEventType();while(ev!=XmlPullParser.END_DOCUMENT){if(ev==XmlPullParser.START_TAG){depth++;tag=local(p.getName());if("Media".equals(tag)||"Media2".equals(tag))mediaDepth=depth;}else if(ev==XmlPullParser.TEXT&&mediaDepth>0&&"XAddr".equals(tag)){String v=p.getText().trim();if(v.length()>0)return v;}else if(ev==XmlPullParser.END_TAG){if(depth==mediaDepth)mediaDepth=-1;depth--;}ev=p.next();}}catch(Exception ignored){}return"";}
    private static String findAnyXAddr(String xml){return findText(xml,"XAddr",null);}private static String local(String n){int c=n.indexOf(':');return c>=0?n.substring(c+1):n;}private static String escape(String x){return x.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
    private static byte[] readAll(InputStream in)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] x=new byte[8192];int n;while((n=in.read(x))>=0)b.write(x,0,n);return b.toByteArray();}
    private void add(LinearLayout c,String k,String v){if(v.length()==0)return;LinearLayout r=ClientUi.row(this);r.addView(ClientUi.text(this,k,12,ClientUi.MUTED,true),new LinearLayout.LayoutParams(ClientUi.dp(this,115),ViewGroup.LayoutParams.WRAP_CONTENT));TextView value=ClientUi.text(this,v,13,ClientUi.NAVY,false);value.setTextIsSelectable(true);r.addView(value,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));c.addView(r,ClientUi.margins(this,ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT,0,6,0,6));}
    static final class Profile{String token="",name="";}
}
